def transform(grid):
    h, w = len(grid), len(grid[0])
    panels = []
    # A one-cell solid separator divides the two equal-sized panels.
    if h % 2 == 1:
        r = h // 2
        if len(set(grid[r])) == 1:
            panels.append((grid[:r], grid[r + 1:]))
    if w % 2 == 1:
        c = w // 2
        if len({grid[r][c] for r in range(h)}) == 1:
            panels.append(([row[:c] for row in grid], [row[c + 1:] for row in grid]))
    if not panels:
        raise ValueError('no centered solid separator')
    a, b = panels[0]
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    if len(common) != 1:
        raise ValueError('expected one color shared by both panels')
    key = next(iter(common))
    # The shared color is the canvas; mark aligned occurrences of that color.
    return [[3 if x == key and y == key else key for x, y in zip(ra, rb)]
            for ra, rb in zip(a, b)]
